// SPDX-License-Identifier: Apache-2.0
//
// Verilator harness for tests/test_vga.py: replays a per-clock `uo_out` dump (one byte per
// clock, as written by tt_harness.reference) into VgaTiming and VgaCapture and collects what
// they produce. The top module (generated by the test) wires VgaTiming's polarities to
// VgaCapture and drives its `blank` from VgaTiming's `no_signal`, as software does.
//
//     Vtop --dump FILE --clocks N [--settings DIV H_OFFSET V_OFFSET H_STEP V_STEP]
//          [--size WIDTH HEIGHT --out FILE]
//
// Clock c presents byte c on `uo_out`; the outputs are read in that clock, before its edge
// (registers show what the clocks before c produced), as in the Migen-simulator tests.
//
// Prints one line on standard output:
//
//     clocks_per_line=800 lines_per_frame=525 hsync_width=96 vsync_lines=2 hsync_positive=1
//     vsync_positive=1 frames=3 locked=1 no_signal=0 first_publish=813601 first_locked=1233601
//     frames_done=5 writes=1536000
//
// (on one line; first_* are -1 if never). With --out, a snapshot of the framebuffer is
// appended to FILE at every `frame_done`: the clock (8 bytes, little endian), then WIDTH *
// HEIGHT bytes of 6-bit pixels, row-major. The framebuffer is a shadow of what the write port
// wrote, starting zeroed. Exit status: 0 done; 2 bad arguments or unreadable dump.

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iterator>
#include <memory>
#include <string>
#include <vector>

#include "Vtop.h"
#include "verilated.h"

namespace {

void tick(Vtop& top) {
    top.sys_clk = 0;
    top.eval();
    top.sys_clk = 1;
    top.eval();
}

[[noreturn]] void usage(const char* why) {
    std::fprintf(stderr, "vga_tb: %s\n", why);
    std::exit(2);
}

}  // namespace

int main(int argc, char** argv) {
    const std::unique_ptr<VerilatedContext> ctx{new VerilatedContext};
    ctx->commandArgs(argc, argv);
    const auto top = std::make_unique<Vtop>(ctx.get());

    std::string dump_path;
    std::string out_path;
    uint64_t clocks = 0;
    unsigned width = 0;
    unsigned height = 0;
    unsigned settings[5] = {1, 1, 1, 1, 1};
    for (int i = 1; i < argc; i++) {
        const std::string arg = argv[i];
        auto next = [&](int k) -> const char* {
            if (i + k >= argc) usage(("missing value after " + arg).c_str());
            return argv[i + k];
        };
        if (arg == "--dump") {
            dump_path = next(1);
            i += 1;
        } else if (arg == "--clocks") {
            clocks = std::strtoull(next(1), nullptr, 10);
            i += 1;
        } else if (arg == "--out") {
            out_path = next(1);
            i += 1;
        } else if (arg == "--size") {
            width = static_cast<unsigned>(std::strtoul(next(1), nullptr, 10));
            height = static_cast<unsigned>(std::strtoul(next(2), nullptr, 10));
            i += 2;
        } else if (arg == "--settings") {
            for (int k = 0; k < 5; k++) settings[k] = std::strtoul(next(k + 1), nullptr, 10);
            i += 5;
        } else if (arg.rfind("+verilator", 0) == 0) {
            continue;
        } else {
            usage(("unknown argument " + arg).c_str());
        }
    }
    if (dump_path.empty() || clocks == 0) usage("--dump and --clocks are required");
    if (!out_path.empty() && (width == 0 || height == 0)) usage("--out needs --size");

    std::ifstream in(dump_path, std::ios::binary);
    if (!in) usage("cannot open the dump");
    std::vector<uint8_t> dump((std::istreambuf_iterator<char>(in)),
                              std::istreambuf_iterator<char>());
    if (dump.size() < clocks) usage("the dump is shorter than --clocks");

    FILE* out = nullptr;
    if (!out_path.empty()) {
        out = std::fopen(out_path.c_str(), "wb");
        if (!out) usage("cannot write --out");
    }
    std::vector<uint8_t> shadow(static_cast<size_t>(width) * height, 0);

    top->sys_clk = 0;
    top->divider = settings[0];
    top->h_offset = settings[1];
    top->v_offset = settings[2];
    top->h_step = settings[3];
    top->v_step = settings[4];

    long long first_publish = -1;
    long long first_locked = -1;
    uint64_t frames_done = 0;
    uint64_t writes = 0;
    for (uint64_t c = 0; c < clocks; c++) {
        top->uo_out = dump[c];
        top->eval();
        if (first_publish < 0 && top->frames > 0) first_publish = static_cast<long long>(c);
        if (first_locked < 0 && top->locked) first_locked = static_cast<long long>(c);
        if (top->frame_done) {
            frames_done++;
            if (out) {
                for (int b = 0; b < 8; b++) std::fputc(static_cast<int>((c >> (8 * b)) & 0xFF), out);
                std::fwrite(shadow.data(), 1, shadow.size(), out);
            }
        }
        if (top->we) {
            writes++;
            if (top->addr < shadow.size()) shadow[top->addr] = top->data;
        }
        tick(*top);
    }
    if (out) std::fclose(out);

    std::printf(
        "clocks_per_line=%u lines_per_frame=%u hsync_width=%u vsync_lines=%u hsync_positive=%u "
        "vsync_positive=%u frames=%u locked=%u no_signal=%u first_publish=%lld first_locked=%lld "
        "frames_done=%llu writes=%llu\n",
        static_cast<unsigned>(top->clocks_per_line), static_cast<unsigned>(top->lines_per_frame),
        static_cast<unsigned>(top->hsync_width), static_cast<unsigned>(top->vsync_lines),
        static_cast<unsigned>(top->hsync_positive), static_cast<unsigned>(top->vsync_positive),
        static_cast<unsigned>(top->frames), static_cast<unsigned>(top->locked),
        static_cast<unsigned>(top->no_signal), first_publish, first_locked,
        static_cast<unsigned long long>(frames_done), static_cast<unsigned long long>(writes));
    std::fflush(stdout);
    top->final();
    return 0;
}
